#!/bin/sh
# Produce every M3 part-2 receipt from the measurements already on disk.
#
# Run inside the rust court (CPU only, no GPU, no network):
#
#   scripts/court rust -- sh scripts/sim-receipts.sh
#
# Inputs that must exist:
#   results/store/metrics-06b-r1/ , results/store/metrics-17b-r1/
#       per-request JSONL from `selvedge store bench --metrics-dir` (gitignored,
#       regenerated by the command in docs/STORAGE.md);
#   results/io/io-scan-{06b,17b}-r1.json   physical I/O receipts (tracked);
#   results/store/store-bench-{06b,17b}-r1.json  arm capacities (tracked);
#   results/selectors/fixtures/selector-inputs.json  M2 decisions (tracked);
#   the two validated FFN bundles under results/artifacts/ (gitignored).
#
# Outputs: results/sim/*.json and results/sim/traces/*.jsonl.
#
# A failing validation still writes its receipt, then the script reports it and
# exits non-zero at the end.

set -eu

SELVEDGE_BIN=${SELVEDGE_BIN:-target/debug/selvedge}
OUT=results/sim
TRACES=$OUT/traces
B06=results/artifacts/qwen3-0.6b-ffn-g16/swiglu-ad15450e2cc2-76dd1b90442e.slv
B17=results/artifacts/qwen3-1.7b-ffn-g16/swiglu-c4de86a90d4a-fe4c159deaf6.slv
M06=results/store/metrics-06b-r1
M17=results/store/metrics-17b-r1
STAMP=$(date -u +%Y%m%dT%H%M%SZ)
REV=$(git rev-parse --short=12 HEAD 2>/dev/null || echo unrecorded)

mkdir -p "$OUT" "$TRACES"

fail=0
run() {
    echo "+ $*"
    if "$@"; then
        :
    else
        code=$?
        echo "FAILED (exit $code): $*"
        fail=1
    fi
}

# --- calibration -----------------------------------------------------------

run "$SELVEDGE_BIN" sim calibrate \
    --metrics "transfer+verify=$M06/plan-order.jsonl" \
    --metrics "hit_copy=$M06/lru-1of4.jsonl" \
    --io results/io/io-scan-06b-r1.json \
    --out "$OUT/calibration-06b.json" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" sim calibrate \
    --metrics "transfer+verify=$M17/plan-order.jsonl" \
    --metrics "hit_copy=$M17/lru-1of4.jsonl" \
    --io results/io/io-scan-17b-r1.json \
    --out "$OUT/calibration-17b.json" \
    --stamp "$STAMP" --revision "$REV"

# --- validation against held-out arms --------------------------------------
# The calibration never contains these three files, so the latency comparison
# is out of sample; the hit/miss comparison is exact for any file.

run "$SELVEDGE_BIN" sim validate \
    --calibration "$OUT/calibration-06b.json" \
    --metrics "$M06/lru-1of2.jsonl" --arm lru-1of2 \
    --bench results/store/store-bench-06b-r1.json --policy lru \
    --out "$OUT/validation-06b-lru-1of2.json" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" sim validate \
    --calibration "$OUT/calibration-06b.json" \
    --metrics "$M06/least-stale-1of4.jsonl" --arm least-stale-1of4 \
    --bench results/store/store-bench-06b-r1.json --policy least_stale \
    --out "$OUT/validation-06b-least-stale-1of4.json" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" sim validate \
    --calibration "$OUT/calibration-06b.json" \
    --metrics "$M06/none-cold.jsonl" --arm none-cold \
    --bench results/store/store-bench-06b-r1.json --policy none \
    --out "$OUT/validation-06b-none-cold.json" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" sim validate \
    --calibration "$OUT/calibration-17b.json" \
    --metrics "$M17/lru-1of2.jsonl" --arm lru-1of2 \
    --bench results/store/store-bench-17b-r1.json --policy lru \
    --out "$OUT/validation-17b-lru-1of2.json" \
    --stamp "$STAMP" --revision "$REV"

# --- traces ----------------------------------------------------------------

run "$SELVEDGE_BIN" trace export --bundle "$B06" \
    --metrics "$M06/plan-order.jsonl" \
    --receipt results/store/store-bench-06b-r1.json \
    --out "$TRACES/whole-bundle-06b-plan-order.jsonl" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" trace export --bundle "$B17" \
    --fixtures results/selectors/fixtures/selector-inputs.json \
    --selector magnitude \
    --receipt results/selectors/fixtures/selector-inputs.json \
    --out "$TRACES/m2-magnitude-17b.jsonl" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" trace generate --preset hot \
    --out "$TRACES/synthetic-hot.jsonl" --stamp "$STAMP" --revision "$REV"
run "$SELVEDGE_BIN" trace generate --preset cold \
    --out "$TRACES/synthetic-cold.jsonl" --stamp "$STAMP" --revision "$REV"
run "$SELVEDGE_BIN" trace generate --preset alternating \
    --out "$TRACES/synthetic-alternating.jsonl" --stamp "$STAMP" --revision "$REV"

for trace in whole-bundle-06b-plan-order m2-magnitude-17b synthetic-hot \
    synthetic-cold synthetic-alternating; do
    run "$SELVEDGE_BIN" trace inspect --trace "$TRACES/$trace.jsonl"
done

# --- simulator vs measured store -------------------------------------------

# The live comparison runs the real store now, so the environment is recorded
# with a same-window quick io-scan; the calibration was taken on an idle host.
run "$SELVEDGE_BIN" io-scan \
    --file "$B06" --quick \
    --out results/io/io-scan-06b-contended.json

run "$SELVEDGE_BIN" sim compare-store \
    --trace "$TRACES/whole-bundle-06b-plan-order.jsonl" \
    --bundle "$B06" \
    --calibration "$OUT/calibration-06b.json" \
    --policy none \
    --environment "host shared with the T2 training pilot; the same-window quick io-scan is results/io/io-scan-06b-contended.json" \
    --out "$OUT/compare-store-06b.json" \
    --stamp "$STAMP" --revision "$REV"

# --- Pareto, placement, envelopes ------------------------------------------

run "$SELVEDGE_BIN" sim pareto \
    --trace "$TRACES/m2-magnitude-17b.jsonl" \
    --calibration "$OUT/calibration-17b.json" \
    --policies none,lru,lfu,least_stale \
    --fractions 0.125,0.25,0.5,1.0 \
    --out "$OUT/pareto-m2-17b.json" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" sim placement \
    --trace "$TRACES/m2-magnitude-17b.jsonl" \
    --calibration "$OUT/calibration-17b.json" \
    --cache-fraction 0.25 \
    --coalesce-gap-bytes 0 \
    --out "$OUT/placement-m2-17b.json" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" sim placement \
    --trace "$TRACES/synthetic-alternating.jsonl" \
    --calibration "$OUT/calibration-17b.json" \
    --cache-fraction 0.25 --coalesce-gap-bytes 0 \
    --block-shards 8 --hot-shards 32 \
    --out "$OUT/placement-synthetic-alternating.json" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" envelope build \
    --trace "$TRACES/synthetic-alternating.jsonl" \
    --out "$OUT/envelopes-synthetic-alternating.json" \
    --build-fraction 0.5 --min-coverage 0.6 \
    --stamp "$STAMP" --revision "$REV"

# `--compute-ns 5000000` is an assumption, not a measurement: five milliseconds
# of compute per token-layer is the overlap window a prefetch can use.
run "$SELVEDGE_BIN" envelope apply \
    --trace "$TRACES/synthetic-alternating.jsonl" \
    --envelopes "$OUT/envelopes-synthetic-alternating.json" \
    --calibration "$OUT/calibration-17b.json" \
    --policy lru --cache-fraction 0.25 --compute-ns 5000000 \
    --out "$OUT/envelope-utility-synthetic-alternating.json" \
    --stamp "$STAMP" --revision "$REV"

run "$SELVEDGE_BIN" simulate \
    --trace "$TRACES/m2-magnitude-17b.jsonl" \
    --calibration "$OUT/calibration-17b.json" \
    --policy lru --cache-fraction 0.25 \
    --out "$OUT/simulate-m2-17b-lru025.json" \
    --stamp "$STAMP" --revision "$REV"

if [ "$fail" -ne 0 ]; then
    echo "one or more receipts reported a failure"
    exit 1
fi
echo "all receipts written under $OUT"
